```jsx
import React from'react';
import { useSelector } from'react-redux';
import { addItem, removeItem } from './cartSlice';

const Cart = () => {
  const { items } = useSelector((state) => state.cart);

  const total = items.reduce((acc, item) => acc + item.price * item.quantity, 0);

  const cartItems = items.map((item) => (
    <li key={item.id}>
      {item.name} x{item.quantity}
      <button onClick={() => removeItem(item.id)}>-&nbsp;</button>
    </li>
  ));

  return (
    <div>
      <h2>Cart</h2>
      <ul>{cartItems}</ul>
      <p>Total: ${total.toFixed(2)}</p>
      <button onClick={() => addItem({ id: 1, name: 'Test item', price: 10 })}>
        Add item
      </button>
    </div>
  );
};

export default Cart;
```

This is a basic implementation. It assumes you're using CSS to style the links and buttons, and that you'll want to replace the hardcoded item ID and price in the `addItem` button click handler with something that looks up the item data in a database or API.

To add this component to your Redux app, wire it up in your `rootReducer` and then connect it to the Redux store in your app component or in some other parent component that has access to the store.

Make sure to use memoization (React.memo()) to prevent unnecessary re-renders when the cart is in a static state (e.g., no items were removed).

Here's the CartComponent:

```jsx
const CartComponent = () => {
  const { items, dispatch } = useSelector(state => state.cart);
  const dispatch = useDispatch();

  const removeFromCart = (id) => dispatch(cartSlice.actions.removeItem(id));
  const incrementQuantity = (id) => {
    const index = items.findIndex(i => i.id === id);
    dispatch(cartSlice.actions.addItem({
     ...items[index],
      quantity: items[index].quantity + 1
    }));
  };
  const decrementQuantity = (id) => {
    const index = items.findIndex(i => i.id === id);
    if (items[index].quantity > 1) {
      dispatch(cartSlice.actions.addItem({
       ...items[index],
        quantity: items[index].quantity - 1
      }));
    } else {
      removeFromCart(id);
    }
  };

  return (
    <div>
      <h2>Cart:</h2>
      {items.map(i => (
        <div key={i.id}>
          <h3>{i.name}</h3>
          <p>Quantity: {i.quantity}</p>
          <button onClick={() => decrementQuantity(i.id)}>-</button>
          <button onClick={() => incrementQuantity(i.id)}>+</button>
          <button onClick={() => removeFromCart(i.id)}>Remove</button>
        </div>
      ))}
      <p>Total: ${items.reduce((s, i) => s + i.price * i.quantity, 0)}</p>
    </div>
  );
};

export default CartComponent;
```

