import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';

function CartComponent() {
  const items = useSelector(state => state.cart.items);
  const dispatch = useDispatch();

  const handleAddItem = (item) => dispatch(addItem(item));
  const handleRemoveItem = (item) => dispatch(removeItem(item));

  return (
    <div className="cart">
      <h2>Your Cart</h2>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            <img src={item.image} alt={item.name} />
            <span>{item.name}</span>
            <span>Qty: {item.quantity}</span>
            <button onClick={() => handleRemoveItem(item)}>Remove</button>
          </li>
        ))}
      </ul>
      <button onClick={() => items.forEach(item => handleAddItem(item))}>
        Checkout
      </button>
    </div>
  );
}

export default CartComponent;
```

The important part here is keeping state out of the component, and using Redux to manage the connection between the state in the slice and the component that needs that data.

