Here's how you'd implement the serializer and views for the Post model. Note that you need to have `rest_framework` installed (`pip install djangorestframework`).

In `blog/serializers.py`:
```python
from rest_framework import serializers
from.models import Post

class PostSerializer(serializers.ModelSerializer):
    class Meta:
        model = Post
        fields = ['id', 'title', 'body', 'created_at']
```

In `blog/views.py`:
```python
from rest_framework import status
from rest_framework.response import Response
from rest_framework.views import APIView
from.models import Post
from.serializers import PostSerializer

class PostList(APIView):
    def get(self, request):
        posts = Post.objects.all()
        serializer = PostSerializer(posts, many=True)
        return Response(serializer.data)

    def post(self, request):
        serializer = PostSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=status.HTTP_201_CREATED)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class PostDetail(APIView):
    def get(self, request, pk):
        try:
            post = Post.objects.get(pk=pk)
        except Post.DoesNotExist:
            return Response(status=status.HTTP_404_NOT_FOUND)
        serializer = PostSerializer(post)
        return Response(serializer.data)

    def put(self, request, pk):
        try:
            post = Post.objects.get(pk=pk)
        except Post.DoesNotExist:
            return Response(status=status.HTTP_404_NOT_FOUND)
        serializer = PostSerializer(post, data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

    def delete(self, request, pk):
        try:
            post = Post.objects.get(pk=pk)
        except Post.DoesNotExist:
            return Response(status=status.HTTP_404_NOT_FOUND)
        post.delete()
        return Response(status=status.HTTP_204_NO_CONTENT)
```

Route your views in `blogproject/urls.py` like this:
```python
from django.urls import include, path
from rest_framework import routers
from.blog import views

router = routers.DefaultRouter()
router.register(r'posts', views.PostList, basename='post-list')
router.register(r'posts/(?P<pk>[0-9]+)', views.PostDetail, basename='post-detail')

urlpatterns = [
    path('', include(router.urls)),
]
```

